from pathlib import Path
import ast, json, html

root=Path.cwd()
old=ast.parse((root/'.lavish/assets/makers-polish/build-overview.py').read_text())
style=next(ast.literal_eval(n.value) for n in old.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='style' for t in n.targets))
style=style.replace('assets/makers-polish','assets/makers-type')
style+='''
@font-face{font-family:ReviewLight;src:url(assets/makers-type/fonts/PlusJakartaSans-Light-300.woff2);font-weight:300;font-display:swap}
.weight-study{padding:34px;background:var(--light);border-radius:18px;margin-bottom:32px}.weight-study h2{margin-bottom:24px;color:var(--red)}.weight-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:48px}.weight-pair article{min-width:0}.weight-pair .meta{font:600 13px/1.5 Body;margin-bottom:18px}.weight-copy{font:400 17px/1.6 Body;max-width:57ch}.weight-copy.light{font-family:ReviewLight,Body,sans-serif;font-weight:300}.weight-copy strong{font-family:Body;font-weight:600}.weight-study small{display:block;margin-top:22px;font-size:13px;max-width:90ch}.choice-note{padding:20px 0 0;display:flex;flex-wrap:wrap;gap:18px;align-items:center}.choice-note label{display:flex;gap:10px;align-items:center;min-height:44px}.choice-note input{accent-color:var(--red)}.back-example{display:inline-flex;align-items:center;gap:8px;min-width:44px;min-height:44px;color:var(--light);background:var(--red);padding:10px 16px;border-radius:10px;font-size:14px}.back-example svg{width:16px;height:16px}.specimen-note{font-size:14px;max-width:90ch;margin:24px 0 36px}.owner-image{max-height:480px;object-fit:contain;object-position:left top}.review .scope-label{font-weight:600}.review select{max-width:100%;width:100%;min-height:48px;margin:8px 0 20px;padding:10px;border:1px solid var(--red);border-radius:10px;background:var(--light);color:var(--ink)}@media(max-width:760px){.weight-study{padding:24px 20px}.weight-pair{grid-template-columns:1fr;gap:30px}}
'''
items=[
dict(id='T01',title='Make body copy one step lighter.',category='Weight',recommended=True,
 why='The current body is true Plus Jakarta Sans Regular 400. It is correctly loaded, but its strokes feel dense beside the condensed display face.',
 change='Use genuine Light 300 for the hero introduction, commitment/process copy and application introduction. Keep 17px size, 1.6 line height and full text colour. Inputs and secondary instructions stay Regular 400.',
 trade='This is the main taste decision. The preview uses a real 300 font, not reduced opacity or a CSS weight that silently falls back to 400. Adding that face is part of this option.',source='fonts'),
dict(id='T02',title='Give emphasis a clear job.',category='Weight + meaning',recommended=True,
 why='The current explanatory paragraphs have almost no internal emphasis, so a quick scan gives each phrase similar importance.',
 change='Use Semibold 600 on one useful phrase per paragraph, such as “a full day” or “does not guarantee selection”. Keep the surrounding words light and preserve the copy.',
 trade='This pairs well with T01. The emphasis comes from weight rather than extra red text, extra words or larger type.',source='audience'),
dict(id='T03',title='Quiet the return link.',category='Navigation',recommended=True,
 why='The back link currently uses the same 17px body size as the introduction and stretches across the hero grid.',
 change='Use a 16px back arrow, a 14px “Edition” label and a 44px-high click target. Keep full-contrast cream and a visible focus state.',
 trade='Arrow + label is my recommendation. If you prefer icon only, choose it below; it still needs a 44px target and an accessible “Back to the edition” name.',source='makers'),
dict(id='T04',title='Separate labels, answers and small print.',category='Form typography',recommended=True,
 why='Form labels are currently 17px Semibold, the same size as entered answers. Help and privacy text drop to 13px, creating a large jump in reading density.',
 change='Use 16px Semibold labels, keep entered answers at 17px Regular, and raise help/privacy/error text to 14px Regular. Keep required markers and error associations intact.',
 trade='The form becomes quieter without making the supporting instructions faint or thin. Its Flux controls and layout stay the same.',source='makers'),
dict(id='T05',title='Treat the date as metadata.',category='Hierarchy',recommended=True,
 why='The date and location currently use the same 17px Regular treatment as the paragraph above.',
 change='Set the date/location line at 14px Regular so it reads as practical detail between the introduction and the application action.',
 trade='Keep the same wording, colour and position. This is a quieter supporting role, with no badge or decorative label.',source='audience'),
dict(id='T06',title='Balance the section headings.',category='Wrapping + scale',recommended=False,
 why='“What you commit to” can leave “to” alone on a line. The application title also uses the same 78px ceiling as the editorial section headings.',
 change='Balance the commitment heading into natural phrases and cap the application title at 68px. Keep the 118px hero and 34px form-group legends.',
 trade='Optional. It gives the application a calmer introduction while keeping the page headline at full poster scale.',source='makers'),
]
esc=lambda s:html.escape(s,quote=True)
rows=[]
for item in items:
    ident=item['id'];panes=''
    for device in ['desktop','mobile']:
        figures=''
        for version,label in [('current','Current page'),('proposed','Combined proposal')]:
            image=f'assets/makers-type/{ident}-{device}-{version}.png'
            figures+=f'<figure><figcaption>{label}</figcaption><a href="{image}" target="_blank" rel="noopener"><img src="{image}" loading="lazy" alt="{esc(item["title"])} {label.lower()} at {device} size"></a></figure>'
        panes+=f'<div class="comparison {device}" data-device="{device}" {"hidden" if device=="mobile" else ""}>{figures}</div>'
    extra=''
    if ident=='T03':
        extra='''<div class="choice-note" role="group" aria-label="Back link treatment"><label><input form="review" type="radio" name="back_style" value="arrow_label" checked>Arrow + Edition</label><label><input form="review" type="radio" name="back_style" value="icon_only">Icon only</label><span class="back-example" aria-hidden="true"><svg viewBox="0 0 20 20" fill="none"><path d="M11.25 4.75 5.75 10l5.5 5.25M6 10h10" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg><span id="back-word">Edition</span></span></div>'''
    rows.append(f'''<article class="decision" id="{ident}"><div class="decision-head"><span class="item-id">{ident}</span><div><p class="category">{item['category']} · {'Recommended' if item['recommended'] else 'Optional'}</p><h2>{item['title']}</h2></div><label class="choice"><input form="review" type="checkbox" name="items" value="{ident}" data-label="{esc(item['title'])}"> Include {ident}</label></div><div class="explanation"><p>{item['why']}</p><p><strong>The proposal.</strong> {item['change']}</p></div><div class="device-switch" role="group" aria-label="Preview size for {ident}"><button type="button" data-device-button="desktop" aria-pressed="true">Desktop</button><button type="button" data-device-button="mobile" aria-pressed="false">Mobile</button></div>{panes}{extra}<p class="trade">{item['trade']} <a href="assets/makers-type/sources/{item['source']}.txt" target="_blank" rel="noopener">Source</a></p></article>''')

script='''
const items=ITEMS,boxes=[...document.querySelectorAll('input[name=items]')],notes=document.querySelector('#notes'),scope=document.querySelector('#scope'),receipt=document.querySelector('#receipt');const key='mam-makers-type-2026-10-18';let queued=false;
function selected(){return boxes.filter(b=>b.checked).map(b=>({id:b.value,label:b.dataset.label,disposition:'implement'}))}
function backStyle(){return document.querySelector('input[name=back_style]:checked').value}
function update(){const s=selected();document.querySelector('#count').textContent=s.length+' of 6 selected';document.querySelector('#selection-summary').textContent=s.length?s.map(i=>i.id+' '+i.label).join(' / '):'Nothing selected yet.';document.querySelector('#back-word').hidden=backStyle()==='icon_only';try{localStorage.setItem(key,JSON.stringify({ids:s.map(i=>i.id),notes:notes.value,scope:scope.value,back:backStyle()}))}catch{}if(queued){receipt.textContent='Selection changed locally. Queue again to update the unsent request.';queued=false}}
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved){boxes.forEach(b=>b.checked=saved.ids.includes(b.value));notes.value=saved.notes||'';scope.value=saved.scope||'makers';document.querySelector('input[name=back_style][value="'+saved.back+'"]').checked=true}}catch{}
boxes.forEach(b=>b.addEventListener('change',update));document.querySelectorAll('input[name=back_style]').forEach(b=>b.addEventListener('change',update));notes.addEventListener('input',update);scope.addEventListener('change',update);update();
document.querySelector('#recommended').onclick=()=>{boxes.forEach(b=>b.checked=items.find(i=>i.id===b.value).recommended);update()};document.querySelector('#clear').onclick=()=>{boxes.forEach(b=>b.checked=false);update()};
document.querySelectorAll('[data-device-button]').forEach(button=>button.onclick=()=>{const row=button.closest('.decision');row.querySelectorAll('[data-device-button]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));row.querySelectorAll('[data-device]').forEach(p=>p.hidden=p.dataset.device!==button.dataset.deviceButton)});
function answer(){return 'Implement these typography choices: '+selected().map(i=>i.id+' '+i.label).join('; ')+'. '+(scope.value==='site'?'Apply the selected shared font-weight and text-role rules consistently across the public site; page-specific back-link, emphasis and heading choices apply to makers.':'Scope changes to /makers and its application form.')+' '+(selected().some(i=>i.id==='T03')?'Back-link style: '+(backStyle()==='icon_only'?'icon only, with accessible name Back to the edition and 44px target.':'arrow + Edition, with accessible name Back to the edition and 44px-high target.'):'')+' Preserve the brand faces, copy, palette, Flux components, field contract and hardened application flow. '+(notes.value.trim()?'Adjustments: '+notes.value.trim()+'. ':'')+'Account for every selected ID with an outcome and verification before reporting completion.'}
document.querySelector('#review').onsubmit=e=>{e.preventDefault();if(!selected().length){receipt.textContent='Choose at least one suggestion first.';return}if(!window.lavish?.queuePrompt){receipt.textContent='Open in Lavish to queue, or copy the selection into the chat.';return}window.lavish.queuePrompt(answer(),{tag:'tracked-batch',queueKey:'makers-type',text:'Typography: '+selected().map(i=>i.id).join(', '),element:e.currentTarget,data:{items:selected(),backLinkStyle:backStyle(),scope:scope.value,notes:notes.value.trim()}});queued=true;receipt.textContent='Queued '+selected().map(i=>i.id).join(', ')+'. Use Send to Agent in Lavish when ready.'};document.querySelector('#copy').onclick=async()=>{if(!selected().length){receipt.textContent='Choose a suggestion first.';return}try{await navigator.clipboard.writeText(answer());receipt.textContent='Copied. Paste in the chat to request implementation.'}catch{const t=document.createElement('textarea');t.value=answer();t.readOnly=true;receipt.replaceChildren(t);t.select()}};
'''.replace('ITEMS',json.dumps(items))

page=f'''<!doctype html><html lang="en" data-lavish-annotate="off"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Makers page · Typography review</title><style>{style}</style></head><body>
<header class="masthead"><div class="topline"><span>Make a Mark Brussels / Typography</span><span>18 October 2026 · Six suggestions</span></div><h1>Lighter text. Clearer emphasis.</h1><p>The display face has its voice. The reading text needs finer weight contrast, and the back link can step back. Six choices, shown with the actual page copy.</p></header>
<nav class="toolbar" aria-label="Review"><span id="count" aria-live="polite">0 of 6 selected</span><a class="button primary" href="#review">Review your selection</a></nav><main class="wrap">
<section class="intro"><div><h2>Start with the weight.</h2><p>Your screenshot points to the main issue: the body has a fairly even weight throughout. The live page uses Regular 400; there is no weight-loading bug. I recommend a true Light 300 for reading copy and Semibold 600 for a small amount of emphasis.</p><p>Keep the same two families, colour, body size and leading. The change should come from the letterforms and their roles.</p></div><aside><h3>My recommendation</h3><p class="recommend">T01–T05.</p><p>T06 is optional. The full proposal includes it so you can judge the quieter application heading.</p><p>The 300 font is a real static Light face, matching the incumbent font version and vertical metrics. These are review assets; the running site is unchanged.</p></aside></section>
<section class="weight-study" aria-labelledby="weight-heading"><h2 id="weight-heading">The same words, two weights.</h2><div class="weight-pair"><article><p class="meta">Regular 400 + Semibold 600</p><p class="weight-copy">Volunteer <strong>a full day</strong> and join a planning meeting beforehand. We select makers and match teams in advance.</p></article><article><p class="meta">Genuine Light 300 + Semibold 600</p><p class="weight-copy light">Volunteer <strong>a full day</strong> and join a planning meeting beforehand. We select makers and match teams in advance.</p></article></div><small>This study isolates the weight change at 17px / 1.6. Both sides use the same emphasis. The page comparisons below show all six proposed refinements together.</small></section>
<div class="all-preview"><a href="assets/makers-type/owner-reference.png" target="_blank" rel="noopener"><strong>Your screenshot</strong><div class="thumb"><img src="assets/makers-type/owner-reference.png" alt="Owner screenshot of the makers hero and commitment section"></div></a><a href="assets/makers-type/desktop-proposed-full.png" target="_blank" rel="noopener"><strong>Open the combined proposal</strong><div class="thumb"><img src="assets/makers-type/desktop-proposed-full.png" alt="Full makers-page render with all proposed type refinements"></div></a></div>
<p class="specimen-note">Current images are fresh browser captures. Proposal images use temporary typography overrides. Click a comparison to inspect it at full size; switch each item to mobile to judge the smaller view.</p>
<nav class="jump" aria-label="Suggestions">{''.join(f'<a class="button" href="#{i["id"]}">{i["id"]}</a>' for i in items)}</nav>{''.join(rows)}
<form id="review" class="review" data-lavish-question="makers-type"><h2>Choose the refinements.</h2><div class="selection"><strong>Your current selection</strong><span id="selection-summary">Nothing selected yet.</span></div><div class="actions"><button id="recommended" type="button">Select T01–T05</button><button id="clear" type="button">Clear</button></div><label class="scope-label" for="scope">Where should shared type rules apply?</label><select id="scope" name="scope"><option value="makers">Makers page only</option><option value="site">Across the public site</option></select><label for="notes">Anything to adjust?</label><textarea id="notes" name="notes" placeholder="For example: keep the date at 17px, or make the back link icon only."></textarea><div class="actions"><button type="submit" class="primary">Queue selected refinements</button><button id="copy" type="button">Copy selection</button></div><p id="receipt" class="status" role="status" aria-live="polite">Choices stay local until you queue them.</p><small>Queue once, then use Send to Agent in Lavish. Your back-link choice is under T03.</small></form>
<details class="sources"><summary>Evidence, font source and review boundaries</summary><ul><li><a href="assets/makers-type/observations.json" target="_blank">Live computed values</a>: body 400 / 17px / 27.2px; labels 600 / 17px / 25.5px; helper/privacy 400 / 13px / 20.8px; back link 400 / 17px.</li><li><a href="assets/makers-type/sources/fonts.txt" target="_blank">Current font declarations</a> and <a href="assets/makers-type/fonts/SOURCE.md" target="_blank">font provenance</a> establish that the current Jakarta assets are static 400 and 600. Merely writing font-weight:300 would still render the 400 face.</li><li>The Light review face is instantiated from the <a href="https://github.com/google/fonts/tree/main/ofl/plusjakartasans" target="_blank" rel="noopener">official Google Fonts source</a>. The <a href="assets/makers-type/fonts/OFL.txt" target="_blank">OFL license</a> and source font are preserved with the artifact.</li><li><a href="assets/makers-type/type-scan.json" target="_blank">Mechanical type scan</a> reports legacy off-scale values, a novelty warning for the pinned Jakarta family, and fallback-sidecar differences. Those do not justify replacing the brand font. The rendered assessment identified the body-weight and role refinements.</li><li><a href="assets/makers-type/sources/design.txt" target="_blank">The project design system</a> supplied the families, palette and shapes. Proposed body sizes are expressed in rem, and the back action keeps a 44px target. Desktop/mobile proposals have zero horizontal overflow.</li><li>This is a typography review, not a replacement identity or a form redesign. Shipping Light 300 would include proper font-face coverage/loading and fallback definitions; no production font or page file has been changed.</li></ul></details>
<footer class="end"><span>Design source: the project's Brussels broadsheet identity.</span><span>Real weights. Same words. Select what you want built.</span></footer></main><script>{script}</script></body></html>'''
(root/'.lavish/makers-type.html').write_text(page)
print('.lavish/makers-type.html')
